// 공백으로 나뉜 후위 표기식을 계산
stack<int> s;
for (string tok : tokens) {
    if (tok is a number) s.push(value of tok);
    else {
        int b = s.top(); s.pop();
        int a = s.top(); s.pop();
        s.push(a (tok) b);         // + - * / 중 하나
    }
}
// 답은 s.top()

